-- 📚 꼭집 주거 사전 — 배점 항목별 최고점 · 국민·매입·영구 · 2026
-- 재계산 SQL(관리 API에서 그대로 실행 · 읽기만). 범위: 공고일 2026년 · 갈래 「배점·가점」 정책 행 · 항목 낱말 뒤 다음 동그라미 번호(①~⑨) 전까지 250자 안의 「N점」 중 최댓값(30 이하) — 정규식 근사.
-- 확인 2026-10-14 · 결과 요지: 국민 납입횟수 {6:28} · 거주기간 {3:27,6:1} · 미성년자녀 {3:27,5:1} / 매입 납입횟수 {3:42} · 거주기간 {3:30} · 미성년자녀 {4:5} / 영구 거주기간 {20:2,30:6} · 미성년자녀 {7:2,15:1} / 신혼희망 거주기간 {3:1}
with a as(select distinct on(x.announcement_id)x.announcement_id,coalesce(m.std_type,x.housing_type)std,extract(year from coalesce(x.announcement_date,x.created_at::date))::int yr from announcements x left join housing_type_map m on m.source_table='announcements' and m.source=x.source and m.housing_type=x.housing_type order by x.announcement_id,(x.source='LH')desc,x.created_at desc),y as(select p.announcement_id,regexp_replace(p.content_raw,'\s+',' ','g')t,coalesce(r.class_name,c.class_name)cls,a.std from announcement_policies p join a using(announcement_id) left join policy_row_classes r on r.policy_id=p.id and r.axis='standard' left join policy_category_classes c on c.category=p.category and c.axis='standard' where a.yr=2026),seg as(select announcement_id,std,k,s from y cross join lateral(values('납입횟수',substring(t from '납입\s*횟수[^①②③④⑤⑥⑦⑧⑨]{0,250}')),('거주기간',substring(t from '(?:계속\s*거주|연속\s*거주|거주\s*기간|거주한\s*기간)[^①②③④⑤⑥⑦⑧⑨]{0,250}')),('미성년자녀',substring(t from '미성년\s*자녀[^①②③④⑤⑥⑦⑧⑨]{0,250}')))v(k,s) where cls='배점·가점' and s is not null),mx as(select announcement_id,std,k,max(m[1]::int)mp from seg cross join lateral regexp_matches(s,'(\d{1,2})\s*점','g')m where m[1]::int<=30 group by 1,2,3)select std,k,sum(n)anns,json_object_agg(mp,n order by mp)dist from(select std,k,mp,count(*)n from mx group by 1,2,3)q group by std,k order by std,k;
